    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-886e2438c530cfcb0c1cd03a0e3e' AND status='running' AND operation_hash='886e2438c530cfcb0c1cd03a0e3e630f285c3698d38afbd6fd633593dd36128b' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
